/**
 * Built-in drum sounds, synthesised in plain JavaScript into PCM buffers.
 *
 * These are original sounds generated by this code (analog-style drum synthesis recipes),
 * so they carry no third-party licensing requirements and need no network requests. They
 * are rendered once at start-up and then behave exactly like imported samples (tuning,
 * start/end points, envelopes all apply).
 */

export const SYNTH_SAMPLE_RATE = 44100;

export interface BuiltinSound {
  id: string;
  name: string;
  category: string;
  render(sampleRate: number): Float32Array<ArrayBuffer>;
}

/** Deterministic PRNG (mulberry32) so the built-in kit is identical on every load. */
export function rng(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) >>> 0;
    let t = a;
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

type FilterType = 'lowpass' | 'highpass' | 'bandpass';

/** In-place RBJ biquad filter. */
export function biquad(buf: Float32Array<ArrayBuffer>, type: FilterType, freq: number, q: number, sr: number): Float32Array<ArrayBuffer> {
  const w0 = (2 * Math.PI * Math.min(freq, sr * 0.49)) / sr;
  const cos = Math.cos(w0);
  const alpha = Math.sin(w0) / (2 * q);
  let b0: number, b1: number, b2: number;
  if (type === 'lowpass') {
    b0 = (1 - cos) / 2;
    b1 = 1 - cos;
    b2 = (1 - cos) / 2;
  } else if (type === 'highpass') {
    b0 = (1 + cos) / 2;
    b1 = -(1 + cos);
    b2 = (1 + cos) / 2;
  } else {
    b0 = alpha;
    b1 = 0;
    b2 = -alpha;
  }
  const a0 = 1 + alpha;
  const a1 = -2 * cos;
  const a2 = 1 - alpha;
  let x1 = 0,
    x2 = 0,
    y1 = 0,
    y2 = 0;
  for (let i = 0; i < buf.length; i++) {
    const x = buf[i];
    const y = (b0 * x + b1 * x1 + b2 * x2 - a1 * y1 - a2 * y2) / a0;
    x2 = x1;
    x1 = x;
    y2 = y1;
    y1 = y;
    buf[i] = y;
  }
  return buf;
}

function noise(len: number, seed: number): Float32Array<ArrayBuffer> {
  const r = rng(seed);
  const out = new Float32Array(len);
  for (let i = 0; i < len; i++) out[i] = r() * 2 - 1;
  return out;
}

/** Normalise peak level and fade the tail to avoid clicks. */
export function finish(buf: Float32Array<ArrayBuffer>, sr: number, peak = 0.9): Float32Array<ArrayBuffer> {
  let max = 0;
  for (let i = 0; i < buf.length; i++) max = Math.max(max, Math.abs(buf[i]));
  const g = max > 0 ? peak / max : 1;
  const fade = Math.min(buf.length, Math.round(sr * 0.005));
  for (let i = 0; i < buf.length; i++) {
    let v = buf[i] * g;
    const fromEnd = buf.length - 1 - i;
    if (fromEnd < fade) v *= fromEnd / fade;
    buf[i] = v;
  }
  // Short fade-in to avoid a DC step on the very first sample.
  const fadeIn = Math.min(buf.length, 8);
  for (let i = 0; i < fadeIn; i++) buf[i] *= i / fadeIn;
  return buf;
}

function kick(sr: number, opts: { f0: number; f1: number; sweep: number; decay: number; len: number; click: number; drive: number }): Float32Array<ArrayBuffer> {
  const n = Math.round(opts.len * sr);
  const out = new Float32Array(n);
  let phase = 0;
  const clickNoise = noise(n, 11);
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    const f = opts.f1 + (opts.f0 - opts.f1) * Math.exp(-t / opts.sweep);
    phase += (2 * Math.PI * f) / sr;
    const amp = Math.exp(-t / opts.decay);
    const click = opts.click * clickNoise[i] * Math.exp(-t / 0.0015);
    out[i] = Math.tanh(opts.drive * (Math.sin(phase) * amp + click)) / Math.tanh(opts.drive);
  }
  return out;
}

function snare(sr: number, opts: { tone1: number; tone2: number; toneDecay: number; noiseDecay: number; noiseHp: number; mix: number; len: number }): Float32Array<ArrayBuffer> {
  const n = Math.round(opts.len * sr);
  const nz = biquad(noise(n, 23), 'highpass', opts.noiseHp, 0.7, sr);
  biquad(nz, 'lowpass', 9000, 0.7, sr);
  const out = new Float32Array(n);
  let p1 = 0,
    p2 = 0;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    const bend = 1 + 0.4 * Math.exp(-t / 0.01);
    p1 += (2 * Math.PI * opts.tone1 * bend) / sr;
    p2 += (2 * Math.PI * opts.tone2 * bend) / sr;
    const tone = (Math.sin(p1) * 0.6 + Math.sin(p2) * 0.4) * Math.exp(-t / opts.toneDecay);
    const nzEnv = Math.exp(-t / opts.noiseDecay);
    out[i] = tone * (1 - opts.mix) + nz[i] * nzEnv * opts.mix * 1.6;
  }
  return out;
}

const HAT_FREQS = [205.3, 304.4, 369.6, 522.7, 540, 800];

function hat(sr: number, decay: number, len: number, seed: number): Float32Array<ArrayBuffer> {
  const n = Math.round(len * sr);
  const metal = new Float32Array(n);
  const phases = HAT_FREQS.map(() => 0);
  for (let i = 0; i < n; i++) {
    let s = 0;
    for (let k = 0; k < HAT_FREQS.length; k++) {
      phases[k] += (HAT_FREQS[k] * 1.6) / sr;
      s += phases[k] % 1 < 0.5 ? 1 : -1;
    }
    metal[i] = s / HAT_FREQS.length;
  }
  const nz = noise(n, seed);
  for (let i = 0; i < n; i++) metal[i] = metal[i] * 0.7 + nz[i] * 0.3;
  biquad(metal, 'bandpass', 10000, 0.9, sr);
  biquad(metal, 'highpass', 7000, 0.7, sr);
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    metal[i] *= Math.exp(-t / decay) * (1 - Math.exp(-t / 0.0004));
  }
  return metal;
}

function clap(sr: number, opts: { spread: number; tail: number; freq: number; len: number }): Float32Array<ArrayBuffer> {
  const n = Math.round(opts.len * sr);
  const nz = biquad(noise(n, 37), 'bandpass', opts.freq, 1.4, sr);
  biquad(nz, 'highpass', 600, 0.7, sr);
  const out = new Float32Array(n);
  const bursts = [0, opts.spread, opts.spread * 2.1];
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    let env = 0;
    for (const b of bursts) if (t >= b) env = Math.max(env, Math.exp(-(t - b) / 0.007));
    const tailStart = bursts[bursts.length - 1];
    if (t >= tailStart) env = Math.max(env, 0.55 * Math.exp(-(t - tailStart) / opts.tail));
    out[i] = nz[i] * env;
  }
  return out;
}

function rimshot(sr: number): Float32Array<ArrayBuffer> {
  const n = Math.round(0.25 * sr);
  const out = new Float32Array(n);
  const nz = biquad(noise(n, 41), 'highpass', 2000, 0.7, sr);
  let p1 = 0,
    p2 = 0;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    p1 += (2 * Math.PI * 1720) / sr;
    p2 += (2 * Math.PI * 460) / sr;
    const tri = (2 / Math.PI) * Math.asin(Math.sin(p2));
    out[i] = (Math.sin(p1) * 0.55 + tri * 0.6) * Math.exp(-t / 0.018) + nz[i] * 0.5 * Math.exp(-t / 0.004);
  }
  return biquad(out, 'highpass', 300, 0.7, sr);
}

function tom(sr: number, f: number, seed: number): Float32Array<ArrayBuffer> {
  const n = Math.round(0.9 * sr);
  const out = new Float32Array(n);
  const nz = biquad(noise(n, seed), 'lowpass', 3000, 0.7, sr);
  let phase = 0;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    const freq = f * (1 + 0.6 * Math.exp(-t / 0.045));
    phase += (2 * Math.PI * freq) / sr;
    out[i] = Math.sin(phase) * Math.exp(-t / 0.26) + nz[i] * 0.25 * Math.exp(-t / 0.02);
  }
  return out;
}

function cowbell(sr: number): Float32Array<ArrayBuffer> {
  const n = Math.round(0.6 * sr);
  const out = new Float32Array(n);
  let p1 = 0,
    p2 = 0;
  for (let i = 0; i < n; i++) {
    const t = i / sr;
    p1 += 540 / sr;
    p2 += 800 / sr;
    const sq = (p1 % 1 < 0.5 ? 1 : -1) + (p2 % 1 < 0.5 ? 1 : -1);
    const env = 0.6 * Math.exp(-t / 0.015) + 0.4 * Math.exp(-t / 0.12);
    out[i] = sq * env;
  }
  return biquad(out, 'bandpass', 2600, 1.2, sr);
}

export const BUILTIN_SOUNDS: BuiltinSound[] = [
  {
    id: 'builtin:kick-deep',
    name: 'Kick · Deep',
    category: 'Kick',
    render: (sr) => kick(sr, { f0: 160, f1: 47, sweep: 0.04, decay: 0.42, len: 1.4, click: 0.25, drive: 1.6 }),
  },
  {
    id: 'builtin:kick-punch',
    name: 'Kick · Punch',
    category: 'Kick',
    render: (sr) => kick(sr, { f0: 260, f1: 56, sweep: 0.022, decay: 0.16, len: 0.6, click: 0.7, drive: 2.6 }),
  },
  {
    id: 'builtin:snare-classic',
    name: 'Snare · Classic',
    category: 'Snare',
    render: (sr) => snare(sr, { tone1: 185, tone2: 330, toneDecay: 0.07, noiseDecay: 0.13, noiseHp: 1200, mix: 0.55, len: 0.6 }),
  },
  {
    id: 'builtin:snare-tight',
    name: 'Snare · Tight',
    category: 'Snare',
    render: (sr) => snare(sr, { tone1: 238, tone2: 420, toneDecay: 0.04, noiseDecay: 0.075, noiseHp: 2200, mix: 0.62, len: 0.4 }),
  },
  { id: 'builtin:hat-closed', name: 'Hi-hat · Closed', category: 'Hi-hat', render: (sr) => hat(sr, 0.035, 0.3, 53) },
  { id: 'builtin:hat-open', name: 'Hi-hat · Open', category: 'Hi-hat', render: (sr) => hat(sr, 0.32, 1.5, 59) },
  { id: 'builtin:clap', name: 'Clap · Classic', category: 'Clap', render: (sr) => clap(sr, { spread: 0.011, tail: 0.11, freq: 1200, len: 0.7 }) },
  { id: 'builtin:clap-wide', name: 'Clap · Wide', category: 'Clap', render: (sr) => clap(sr, { spread: 0.017, tail: 0.2, freq: 1600, len: 0.9 }) },
  { id: 'builtin:rimshot', name: 'Rimshot', category: 'Percussion', render: (sr) => rimshot(sr) },
  { id: 'builtin:cowbell', name: 'Cowbell', category: 'Percussion', render: (sr) => cowbell(sr) },
  { id: 'builtin:tom-low', name: 'Tom · Low', category: 'Tom', render: (sr) => tom(sr, 92, 61) },
  { id: 'builtin:tom-mid', name: 'Tom · Mid', category: 'Tom', render: (sr) => tom(sr, 135, 67) },
  { id: 'builtin:tom-high', name: 'Tom · High', category: 'Tom', render: (sr) => tom(sr, 190, 71) },
];

const cache = new Map<string, Float32Array<ArrayBuffer>>();

/** Render (and cache) a built-in sound as normalised mono PCM. */
export function renderBuiltin(id: string, sampleRate = SYNTH_SAMPLE_RATE): Float32Array<ArrayBuffer> | null {
  const key = `${id}@${sampleRate}`;
  const hit = cache.get(key);
  if (hit) return hit;
  const def = BUILTIN_SOUNDS.find((s) => s.id === id);
  if (!def) return null;
  const pcm = finish(def.render(sampleRate), sampleRate);
  cache.set(key, pcm);
  return pcm;
}

export function isBuiltin(id: string): boolean {
  return BUILTIN_SOUNDS.some((s) => s.id === id);
}
